Tool response:
Tool: generate_btc_address
Description: Generate Btc Address
Parameters:
    {
      "type": "object",
      "properties": {
        "user_id": {
          "type": "integer",
          "description": "Internal ID of the user requesting the address",
          "title": "User Id"
        },
        "wallet_id": {
          "type": "integer",
          "description": "Internal ID of the BTC wallet to generate address for",
          "title": "Wallet Id"
        }
      },
      "required": [
        "user_id",
        "wallet_id"
      ]
    }

Tool response:
Tool: get_btc_addresses
Description: Get Btc Addresses
Parameters:
    {
      "type": "object",
      "properties": {
        "user_id": {
          "type": "integer",
          "description": "Internal ID of the user whose addresses are being retrieved",
          "title": "User Id"
        },
        "wallet_id": {
          "type": "integer",
          "description": "Internal ID of the BTC wallet to retrieve addresses for",
          "title": "Wallet Id"
        }
      },
      "required": [
        "user_id",
        "wallet_id"
      ]
    }
